public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb) {
    ByteBuf buffer = session.getBuffer();
    buffer.release(); // ensure buffer is released before proceeding
    for (int i = 0; i < str.length(); i++) {
        int codePoint = str.codePointAt(i);
        if (Character.isHighSurrogate(codePoint) && i + 1 < str.length()) {
            int highSurrogate = Character.highSurrogate(codePoint);
            int lowSurrogate = str.codePointAt(i + 1);
            codePoint = Character.toCodePoint(highSurrogate, lowSurrogate);
        }
        buffer.writeByte((byte) codePoint);
    }
    lb.addPointer(buffer.readerIndex(), buffer.writerIndex());
    session.addBuffer(buffer);
    return lb;
}
```

